<?php
namespace App\Console\Commands;
use Illuminate\Console\Command;use Illuminate\Support\Facades\Route;use Illuminate\Support\Facades\Schema;
class WarehouseV2ProductionCheckCommand extends Command {protected $signature='warehouse:v2-production-check';protected $description='Validasi Production Warehouse';public function handle():int{$tables=['wh_bom_headers','wh_bom_items','wh_production_wastes','wh_production_cost_components','wh_production_events'];$missing=array_values(array_filter($tables,fn($t)=>!Schema::hasTable($t)));$routes=['api/v1/warehouse/production-v2/dashboard','api/v1/warehouse/production-v2/boms'];$routeMissing=array_values(array_filter($routes,fn($u)=>!collect(Route::getRoutes())->contains(fn($r)=>$r->uri()===$u)));$this->table(['Check','Result'],[['Missing tables',$missing?implode(', ',$missing):'-'],['Missing routes',$routeMissing?implode(', ',$routeMissing):'-'],['Status',(!$missing&&!$routeMissing)?'PASSED':'FAILED']]);return (!$missing&&!$routeMissing)?self::SUCCESS:self::FAILURE;}}
